const brand = $('Brand Profile & Rules').first().json;
const angles = $('Angle Library').first().json.angles || [];

const hnAutomationRaw = (($('Fetch HN AI Automation').first().json || {}).hits) || [];
const hnOpenAIRaw = (($('Fetch HN OpenAI Agents').first().json || {}).hits) || [];
const devtoRaw = $('Fetch Dev.to AI').all().map((item) => item.json);

const hnAutomation = Array.isArray(hnAutomationRaw) ? hnAutomationRaw : [];
const hnOpenAI = Array.isArray(hnOpenAIRaw) ? hnOpenAIRaw : [];
const devto = Array.isArray(devtoRaw) ? devtoRaw : (Array.isArray(devtoRaw?.result) ? devtoRaw.result : []);

function keywordScore(text) {
  const value = String(text || '').toLowerCase();
  let score = 0;
  const positives = ['agent', 'workflow', 'automation', 'openai', 'n8n', 'api', 'voice', 'assistant', 'operator', 'prompt', 'tool', 'model', 'deployment', 'integration', 'rag', 'open source', 'github', 'chrome', 'extension', 'free', 'template', 'course', 'launch', 'release'];
  const negatives = ['meme', 'drama', 'leak', 'lawsuit', 'celebrity', 'nsfw', 'shitpost', 'funding round', 'hiring', 'opinion'];

  for (const word of positives) if (value.includes(word)) score += 10;
  for (const word of negatives) if (value.includes(word)) score -= 18;

  if (/\b\d{1,3}\b/.test(value)) score += 8;
  if (value.includes('how to')) score += 8;
  if (value.includes('vs')) score += 6;
  if (value.includes('tutorial')) score += 9;
  if (value.includes('case study')) score += 8;
  if (value.includes('without code') || value.includes('no-code')) score += 10;
  if (value.includes('ready')) score += 6;
  if (value.includes('free')) score += 8;
  if (value.includes('open source')) score += 10;

  return score;
}

const normalized = [];

for (const post of hnAutomation) {
  normalized.push({
    source: 'hackernews:ai-automation',
    title: post.title || post.story_title || '',
    url: post.url || post.story_url || '',
    source_score: post.points || 0,
    comments: post.num_comments || 0,
    summary: post._highlightResult?.title?.value
      ? String(post._highlightResult.title.value).replace(/<[^>]+>/g, '').slice(0, 240)
      : '',
  });
}

for (const post of hnOpenAI) {
  normalized.push({
    source: 'hackernews:openai-agents',
    title: post.title || post.story_title || '',
    url: post.url || post.story_url || '',
    source_score: post.points || 0,
    comments: post.num_comments || 0,
    summary: post._highlightResult?.title?.value
      ? String(post._highlightResult.title.value).replace(/<[^>]+>/g, '').slice(0, 240)
      : '',
  });
}

for (const article of devto) {
  normalized.push({
    source: 'dev.to:ai',
    title: article.title || '',
    url: article.url || '',
    source_score: article.public_reactions_count || 0,
    comments: article.comments_count || 0,
    summary: article.description ? String(article.description).slice(0, 240) : '',
  });
}

const deduped = [];
const seen = new Set();

for (const item of normalized) {
  const key = String(item.title || '').trim().toLowerCase();
  if (!key || seen.has(key) || !String(item.url || '').trim()) continue;

  seen.add(key);

  const relevance = keywordScore(item.title + ' ' + item.summary);
  const engagement = Math.min(Number(item.source_score || 0), 400) * 0.08 + Math.min(Number(item.comments || 0), 120) * 0.15;
  const specificity = Math.min((String(item.title || '').split(' ').length || 0), 14) * 0.4;
  const totalScore = Math.round((relevance + engagement + specificity) * 10) / 10;

  deduped.push({
    ...item,
    relevance_score: relevance,
    engagement_score: Math.round(engagement * 10) / 10,
    specificity_score: Math.round(specificity * 10) / 10,
    total_score: totalScore,
    suggested_angles: angles.slice(0, 4),
  });
}

const filtered = deduped
  .filter((item) => item.total_score >= 14)
  .sort((a, b) => b.total_score - a.total_score)
  .slice(0, 10);

const digest = filtered
  .map((item, index) => [
    `${index + 1}. ${item.title}`,
    `source: ${item.source}`,
    `score: ${item.total_score}`,
    `url: ${item.url}`,
    `summary: ${item.summary}`,
  ].join('\n'))
  .join('\n\n');

return [{
  json: {
    brand,
    angles,
    candidates: filtered,
    candidate_digest: digest,
    candidate_count: filtered.length,
    source_debug: {
      hnAutomationCount: hnAutomation.length,
      hnOpenAICount: hnOpenAI.length,
      devtoCount: devto.length,
      devtoType: Array.isArray(devtoRaw) ? 'array' : typeof devtoRaw,
    },
  },
}];

const raw = $json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = { topic: 'parse_failed', angle: 'unknown', hook_ar: '', explainer_ar: '', bullets_ar: [], cta_ar: '', facebook_post: raw, facebook_first_comment: '', x_post: '', hashtags: [], image_prompt: '', reuse_note: 'AI returned non-JSON content. Review manually.', status: 'needs_review' };
}

const selectedRaw = $('OpenAI Topic Selector').first().json.choices?.[0]?.message?.content || '{}';
let selected = {};
try {
  selected = JSON.parse(selectedRaw);
} catch (error) {
  selected = { chosen_title: '', chosen_source: '', chosen_url: '', proof_points: [] };
}

const ranked = $('Normalize & Score Topics').first().json.candidates || [];
const matched = ranked.find((item) => item.url === selected.chosen_url) || ranked[0] || {};

return [{ json: {
  run_timestamp: new Date().toISOString(),
  topic: parsed.topic || selected.chosen_title || matched.title || '',
  angle: parsed.angle || selected.chosen_angle || '',
  source: matched.source || selected.chosen_source || '',
  source_url: matched.url || selected.chosen_url || '',
  source_score: matched.total_score ?? null,
  why_this_topic: selected.why_this_topic || '',
  proof_points: selected.proof_points || [],
  hook_ar: parsed.hook_ar || '',
  explainer_ar: parsed.explainer_ar || '',
  bullets_ar: parsed.bullets_ar || [],
  cta_ar: parsed.cta_ar || '',
  facebook_post: parsed.facebook_post || '',
  facebook_first_comment: parsed.facebook_first_comment || ('المصدر:\n' + (matched.url || selected.chosen_url || '')),
  x_post: parsed.x_post || '',
  hashtags: parsed.hashtags || [],
  image_prompt: parsed.image_prompt || '',
  reuse_note: parsed.reuse_note || '',
  status: parsed.status || 'draft_ready',
  platform_mode: { facebook: 'ready_for_api_publish_plus_comment', x: 'ready_for_manual_publish' }
}}];

const response = $json || {};
const draft = $('Final Draft Output').first().json || {};
const pageNameTarget = 'AZAR';
const pageIdTarget = '177929742707287';

const pages = Array.isArray(response.data) ? response.data : [];
const page = pages.find((item) => String(item.id || '') === pageIdTarget)
  || pages.find((item) => String(item.name || '').trim().toLowerCase() === pageNameTarget.toLowerCase())
  || {};

if (!page.id) {
  throw new Error('The configured Facebook Page was not returned by Meta.');
}
if (!page.access_token) {
  throw new Error('Meta did not return a Page access token. Check the n8n Meta credential and Page permissions.');
}

return [{ json: {
  ...draft,
  page_id: page.id,
  page_name: page.name || pageNameTarget,
  page_access_token: page.access_token,
  page_tasks: page.tasks || [],
  publish_message: draft.facebook_post || '',
  publish_mode: 'facebook_page_feed'
} }];

const commentResult = $json || {};
const postResult = $('Post to Facebook Page').first().json || {};
const draft = $('Prepare Facebook Post').first().json || {};
return [{ json: {
  ...draft,
  facebook_publish_response: postResult,
  facebook_comment_response: commentResult,
  facebook_publish_status: postResult.id ? 'published' : 'unknown',
  facebook_comment_status: commentResult.id ? 'comment_published' : 'comment_skipped_or_failed'
}}];

const postResult = $('Post to Facebook Page').first().json || {};
const draft = $('Prepare Facebook Post').first().json || {};
const postId = postResult.id || '';
const fallback = draft.source_url ? ('المصدر:
' + draft.source_url) : '';
return [{ json: { ...draft, facebook_post_id: postId, facebook_first_comment: draft.facebook_first_comment || fallback } }];
